import type { Resolver } from './../../ricos-types/index.js';
import { getNodeInSelection } from './../../_shared/resolvers/get-node-in-selection.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';

import { RicosCellSelection } from '../tiptap/plugins/cellselection.js';

/**
 * Animation applies to the whole table. The table-selector click produces a
 * RicosCellSelection over ALL cells (a NodeSelection only appears on drag),
 * so treat a whole-table cell selection as selecting the table itself.
 * Partial cell selections resolve to nothing — the button hides there.
 */
export const getTableForAnimation: Resolver<ProseMirrorNode | undefined> = (
  content,
  services,
  editor
): ProseMirrorNode | undefined => {
  const nodeInSelection = getNodeInSelection(content, services, editor);
  if (nodeInSelection) {
    return nodeInSelection;
  }
  const selection = editor?.state?.selection;
  if (selection instanceof RicosCellSelection && selection.isTableSelection()) {
    // $anchorCell resolves *in front of* the cell, so its own depth is the row's — one level
    // up from there is the table
    return selection.$anchorCell.node(-1);
  }
  return undefined;
};
