import {
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  ArrowUp,
  MergeCell,
  SplitCell,
} from '@wix/wix-ui-icons-common/lazy';
import type { ComponentType } from 'react';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type { IToolbarItem, Resolver, ToolbarButton } from './../../../ricos-types/index.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';
import type { ChainedCommands } from './../../../tiptap/core/index.js';

import { TABLE_BUTTONS } from '../../consts.js';
import {
  PLUGIN_TOOLBAR_MERGE_CELLS_BUTTON,
  PLUGIN_TOOLBAR_MOVE_COLUMN_LEFT_BUTTON,
  PLUGIN_TOOLBAR_MOVE_COLUMN_RIGHT_BUTTON,
  PLUGIN_TOOLBAR_MOVE_ROW_DOWN_BUTTON,
  PLUGIN_TOOLBAR_MOVE_ROW_UP_BUTTON,
  PLUGIN_TOOLBAR_SPLIT_CELL_BUTTON,
} from '../../data-hooks.js';
import {
  cannotMergeCellsResolver,
  cannotMoveColumnLeftResolver,
  cannotMoveColumnRightResolver,
  cannotMoveRowDownResolver,
  cannotMoveRowUpResolver,
  cannotSplitCellResolver,
  isCellSelectionResolver,
  isColumnSelectedResolver,
  isRowSelectedResolver,
} from '../resolvers.js';

const SimpleToggleButton = ({
  toolbarItem,
  tooltipKey,
}: {
  toolbarItem: IToolbarItem;
  tooltipKey: string;
}) => {
  const { t } = useContext(RicosContext);
  return (
    <ToolbarButtonComponent
      tooltip={t(tooltipKey)}
      onClick={() => toolbarItem.commands.click()}
      prefix={toolbarItem.presentation?.icon}
      dataHook={toolbarItem.presentation?.dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
      disabled={toolbarItem.attributes.disabled}
    />
  );
};

interface ToggleButtonConfig {
  id: string;
  tooltip: string;
  icon: ComponentType;
  dataHook: string;
  execute: (chain: ChainedCommands) => ChainedCommands;
  disabled: Resolver<boolean>;
  visible: Resolver<boolean>;
}

const createToggleButton = (config: ToggleButtonConfig): ToolbarButton => ({
  id: config.id,
  type: 'toggle',
  tooltip: config.tooltip,
  icon: config.icon,
  dataHook: config.dataHook,
  command: ({ tiptapEditor }) => {
    config.execute(tiptapEditor.chain().focus()).run();
  },
  renderer: toolbarItem => (
    <SimpleToggleButton toolbarItem={toolbarItem} tooltipKey={config.tooltip} />
  ),
  attributes: {
    disabled: config.disabled,
    visible: config.visible,
    alwaysVisible: config.visible,
  },
});

export const createMoveColumnLeftButton = () =>
  createToggleButton({
    id: TABLE_BUTTONS.MOVE_COLUMN_LEFT,
    tooltip: 'TablePlugin_Toolbar_MoveColumnLeft_Tooltip',
    icon: ArrowLeft,
    dataHook: PLUGIN_TOOLBAR_MOVE_COLUMN_LEFT_BUTTON,
    execute: chain => chain.moveColumns('left'),
    disabled: cannotMoveColumnLeftResolver,
    visible: isColumnSelectedResolver,
  });

