import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { DropdownModal } from './../../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../../_shared/list-item-select/list-item-select.js';

import type { CATEGORY, TABLE_COMMANDS_KEYS } from '../../consts.js';
import { INSERT_PANEL_OPTIONS } from './consts.js';

type Props = {
  onClick: (data: {
    commandKey: (typeof TABLE_COMMANDS_KEYS)[keyof typeof TABLE_COMMANDS_KEYS];
  }) => void;
  closeModal: () => void;
  category: (typeof CATEGORY)[keyof typeof CATEGORY];
};

export const InsertDropdown: React.FC<Props> = ({ onClick, closeModal, category }) => {
  const { t, isMobile } = useContext(RicosContext);

  const options = INSERT_PANEL_OPTIONS[category] || [];

  return (
    <DropdownModal
      options={options.map(option => (
        <ListItemSelect
          key={option.key}
          dataHook={option.dataHook}
          title={t(option.title)}
          prefix={isMobile ? <option.icon /> : <option.iconSmall />}
          onSelect={() => {
            onClick({
              commandKey:
                option.commandKey as (typeof TABLE_COMMANDS_KEYS)[keyof typeof TABLE_COMMANDS_KEYS],
            });
            closeModal();
          }}
        />
      ))}
      onCloseButtonClick={closeModal}
      title={t('TablePlugin_Toolbar_ContextMenu_Header_Title')}
    />
  );
};
