import { Box, FormField, Input } from '@wix/design-system';
import React, { useContext, useState } from 'react';

import { PluginsEventsContext, RicosContext } from './../../../ricos-context/index.js';
import { DropdownModal } from './../../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemDivider } from './../../../_shared/list-item-divider/list-item-divider.js';
import { ListItemSelect } from './../../../_shared/list-item-select/list-item-select.js';
import { ListItemToggle } from './../../../_shared/list-item-toggle/list-item-toggle.js';
import { PmNodeType } from './../../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../../_shared/use-node-attrs.js';

import type { CATEGORY } from '../../consts.js';
import { CONTEXT_PANEL_OPTIONS } from './consts.js';

type Props = {
  onClick: (data: { commandKey: string }) => void;
  closeModal: () => void;
  category: (typeof CATEGORY)[keyof typeof CATEGORY];
  nodeId: string;
  showRowHeaderToggle?: boolean;
  showColumnHeaderToggle?: boolean;
  rowHeaderActive?: boolean;
  columnHeaderActive?: boolean;
  altText?: string;
  onAltTextChange?: (text: string) => void;
};

export const ContextDropdown: React.FC<Props> = ({
  onClick,
  closeModal,
  category,
  nodeId,
  showRowHeaderToggle,
  showColumnHeaderToggle,
  rowHeaderActive,
  columnHeaderActive,
  altText,
  onAltTextChange,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const pluginsEvents = useContext(PluginsEventsContext);
  const { pmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.TABLE);
  const rowHeaderSelected = pmNodeAttrs?.tableData
    ? !!pmNodeAttrs.tableData.rowHeader
    : !!rowHeaderActive;
  const colHeaderSelected = pmNodeAttrs?.tableData
    ? !!pmNodeAttrs.tableData.columnHeader
    : !!columnHeaderActive;

  const currentAltText = pmNodeAttrs?.tableData?.altText ?? altText;
  const [localAltText, setLocalAltText] = useState(currentAltText || '');

  const options: JSX.Element[] = [];

  if (showRowHeaderToggle) {
    options.push(
      <ListItemToggle
        key={'toggle-header-row'}
        dataHook={'table-context-toggle-header-row'}
        title={t('TablePlugin_Toolbar_ContextMenu_HeaderRow_Title')}
        selected={rowHeaderSelected}
        onChange={() => onClick({ commandKey: 'toggleHeaderRow' })}
      />
    );
  }

  if (showColumnHeaderToggle) {
    options.push(
      <ListItemToggle
        key={'toggle-header-col'}
        dataHook={'table-context-toggle-header-col'}
        title={t('TablePlugin_Toolbar_ContextMenu_HeaderColumn_Title')}
        selected={colHeaderSelected}
        onChange={() => onClick({ commandKey: 'toggleHeaderColumn' })}
      />
    );
  }

  if (showRowHeaderToggle || showColumnHeaderToggle) {
    options.push(<ListItemDivider key={'divider-hdr'} />);
  }

  if (onAltTextChange) {
    options.push(
      <Box key="alt-text" padding="12px 20px" direction="vertical">
        <FormField
          label={t('TablePlugin_Toolbar_ContextMenu_AltText_Label')}
          infoContent={t('TablePlugin_Toolbar_ContextMenu_AltText_InfoContent')}
        >
          <Input
            size="small"
            dataHook="table-alt-text-input"
            value={localAltText}
            placeholder={t('TablePlugin_Toolbar_ContextMenu_AltText_Placeholder')}
            onChange={e => {
              setLocalAltText(e.target.value);
            }}
            onBlur={() => {
              onAltTextChange(localAltText);
            }}
            onKeyDown={e => {
              if (e.key === 'Enter') {
                onAltTextChange(localAltText);
              }
              e.stopPropagation();
            }}
          />
        </FormField>
      </Box>
    );
    options.push(<ListItemDivider key={'divider-alt-text'} />);
  }

  options.push(
    ...(CONTEXT_PANEL_OPTIONS[category] || []).map((option, index) => {
      if (option === 'divider') {
        return <ListItemDivider key={`divider-${index}`} />;
      }
      const {
        key,
        dataHook,
        title,
        commandKey,
        publishBi,
        icon: Icon,
        iconSmall: IconSmall,
      } = option;

      return (
        <ListItemSelect
          key={key}
          dataHook={dataHook}
          title={t(title)}
          prefix={isMobile ? <Icon /> : <IconSmall />}
          onSelect={() => {
            onClick({ commandKey } as { commandKey: string });
            closeModal();
            publishBi(pluginsEvents, nodeId, category);
          }}
        />
      );
    })
  );

  return (
    <DropdownModal
      options={options}
      onCloseButtonClick={closeModal}
      title={t('TablePlugin_Toolbar_ContextMenu_Header_Title')}
    />
  );
};
