import { ColorBucket } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type { IToolbarItem, RicosServices, ToolbarButton } from './../../../ricos-types/index.js';
import { ColorSwatch } from './../../../_shared/plugin-toolbar/color-swatch.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';

import { TABLE_BUTTONS, TABLE_COLOR_PICKER } from '../../consts.js';
import { PLUGIN_TOOLBAR_BACKGROUND_COLOR_BUTTON } from '../../data-hooks.js';
import { TableCellColorPicker } from '../../modals/table-cell-color-picker.js';
import {
  captureSelectedCellPositions,
  runWithTableCellSelection,
} from '../capture-table-cell-selection.js';
import {
  firstSelectedCellIdResolver,
  getCellBackgroundColorResolver,
  getCellBackgroundColorsResolver,
  selectedCellIdsResolver,
} from '../resolvers.js';
import { createTableStylePreview } from '../table-style-preview.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const BackgroundColorButton: FC<Props> = ({ dataHook, toolbarItem }) => {
  const { t } = useContext(RicosContext);
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);

  const colors: string[] = toolbarItem.attributes.backgroundColors ?? [];
  const hasColors = colors.length > 0;

  return (
    <ToolbarButtonComponent
      ref={setReferenceElement}
      prefix={hasColors ? () => <ColorSwatch colors={colors} /> : ColorBucket}
      onClick={() => {
        toolbarItem.commands.click({ referenceElement });
      }}
      dataHook={dataHook}
      tooltip={t('TablePlugin_Toolbar_BGColor_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};

export const createBackgroundColorButton = (services: RicosServices): ToolbarButton => ({
  id: TABLE_BUTTONS.BACKGROUND_COLOR,
  type: 'modal',
  dataHook: PLUGIN_TOOLBAR_BACKGROUND_COLOR_BUTTON,
  icon: ColorBucket,
  tooltip: 'TablePlugin_Toolbar_BGColor_Tooltip',
  command: ({ modals, tiptapEditor, referenceElement, attributes }) => {
    const modalId = TABLE_COLOR_PICKER;
    const isModalOpen = modals.isModalOpen(modalId);

    if (isModalOpen) {
      modals.closeModal(modalId);
      return;
    }

    const firstCellId = attributes.firstSelectedCellId;
    if (!firstCellId) {
      return;
    }

    const selectedCellPositions = captureSelectedCellPositions(
      tiptapEditor,
      attributes.selectedCellIds
    );
    const backgroundPreview = createTableStylePreview(tiptapEditor, selectedCellPositions);

    modals.togglePluginPanel({
      id: modalId,
      isMobile: services.context.isMobile,
      Component: TableCellColorPicker,
      positioning: { placement: 'bottom', referenceElement },
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      componentProps: {
        modalId,
        nodeId: firstCellId,
        referenceElement,
        onColorPreview: color => {
          backgroundPreview.previewCellBackground(color);
        },
        onColorPreviewEnd: () => {
          backgroundPreview.restore();
        },
        onColorSelected: color => {
          backgroundPreview.restore();
          runWithTableCellSelection(tiptapEditor, selectedCellPositions, () => {
            tiptapEditor
              .chain()
              .focus()
              .updateCellAttribute('cellStyle', { backgroundColor: color })
              .run();
          });
        },
      },
    });
  },
  attributes: {
    backgroundColor: getCellBackgroundColorResolver,
    backgroundColors: getCellBackgroundColorsResolver,
    firstSelectedCellId: firstSelectedCellIdResolver,
    selectedCellIds: selectedCellIdsResolver,
  },
  renderer: toolbarItem => <BackgroundColorButton toolbarItem={toolbarItem} />,
});
