import { TIPTAP_TABLE_CELL_TYPE } from './../../ricos-content/index.js';
import type { Resolver } from './../../ricos-types/index.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import type { Editor } from './../../tiptap/core/index.js';
import type { Node } from './../../tiptap/pm/model.js';

import { getDisplayedBorderOnSide, resolveCellBordersPm } from '../borders/resolve-cell-borders.js';
import { CATEGORY, resolveDefaultBorderColor, resolveDisplayedBorderColor } from '../consts.js';
import { TABLE_DEFAULTS } from '../defaults.js';
import { mergeCells, splitCell } from '../tiptap/commands/mutations.js';
import { TableQuery } from '../tiptap/table-query.js';
import { findTable } from '../tiptap/utilities/find-table.js';
import { isRicosCellSelection } from '../tiptap/utilities/is-selection-type.js';

export type TableSelectionCategory = (typeof CATEGORY)[keyof typeof CATEGORY];

// ---------------------------------------------------------------------------
// Shared selection context — eliminates the repeated
// findTable → TableQuery.of → isRicosCellSelection → getRect preamble
// ---------------------------------------------------------------------------

interface SelectionContext {
  table: TableQuery;
  rect: { left: number; right: number; top: number; bottom: number };
  isCellSelection: true;
}

/**
 * Returns common selection context or null if not in a cell selection inside a table.
 * Most resolvers need exactly this preamble.
 */
const getSelectionContext = (editor: Editor): SelectionContext | null => {
  const { selection } = editor.state;
  if (!findTable(selection)) {
    return null;
  }

  const table = TableQuery.of(selection);
  if (!table || !isRicosCellSelection(selection)) {
    return null;
  }

  const rect = selection.getRect();
  return { table, rect, isCellSelection: true };
};

// ---------------------------------------------------------------------------
// Axis-based resolver helpers — collapse the 4 move + 2 selection resolvers
// ---------------------------------------------------------------------------

type Axis = 'row' | 'col';

const isFullAxisSelected = (ctx: SelectionContext, axis: Axis): boolean => {
  if (ctx.table.isTableSelected()) {
    return false;
  }
  return axis === 'col'
    ? ctx.rect.top === 0 && ctx.rect.bottom === ctx.table.getHeight()
    : ctx.rect.left === 0 && ctx.rect.right === ctx.table.getWidth();
};

const cannotMove = (editor: Editor, axis: Axis, direction: 'start' | 'end'): boolean => {
  const ctx = getSelectionContext(editor);
  if (!ctx) {
    return true;
  }
  if (!isFullAxisSelected(ctx, axis)) {
    return true;
  }

  if (axis === 'col') {
    return direction === 'start' ? ctx.rect.left === 0 : ctx.rect.right >= ctx.table.getWidth();
  }
  return direction === 'start' ? ctx.rect.top === 0 : ctx.rect.bottom >= ctx.table.getHeight();
};

// ---------------------------------------------------------------------------
// Exported resolvers
// ---------------------------------------------------------------------------

// -- Cell attribute resolvers (read from content/node attrs) --

export const getCellBorderColorResolver: Resolver<string | undefined> = content => {
  if (Array.isArray(content) && content.length > 0) {
    return content.find(node => node.type.name === TIPTAP_TABLE_CELL_TYPE)?.attrs?.borderColors
      ?.top;
  }
  return undefined;
};

export const getCellBorderWidthResolver: Resolver<number> = (_, __, editor) => {
  if (!findTable(editor!.state.selection) || !isRicosCellSelection(editor!.state.selection)) {
    return 1;
  }

  let selectedCellWidth: number | undefined;
  editor!.state.selection.forEachCell(node => {
    if (selectedCellWidth !== undefined) {
      return;
    }
    selectedCellWidth = node.attrs.borderWidths?.top;
  });

  return selectedCellWidth || 1;
};

export const getCellSpacingResolver: Resolver<number> = (_, __, editor) => {
  if (!findTable(editor!.state.selection)) {
    return TABLE_DEFAULTS.cellSpacing;
  }

  const table = TableQuery.of(editor!.state.selection);
  if (!table) {
    return TABLE_DEFAULTS.cellSpacing;
  }

  const tableNode = table.getNode();
  return (
    (tableNode.attrs.tableData?.cellSpacing as number | undefined) ?? TABLE_DEFAULTS.cellSpacing
  );
};

export const getCellPaddingResolver: Resolver<number[]> = (_, __, editor) => {
  const defaultPadding = [...TABLE_DEFAULTS.cellPadding];

  if (!findTable(editor!.state.selection)) {
    return defaultPadding;
  }

  const table = TableQuery.of(editor!.state.selection);
  if (!table) {
    return defaultPadding;
  }

  const tableNode = table.getNode();
  const cellPadding = tableNode.attrs.tableData?.cellPadding as number[] | undefined;
  return cellPadding && cellPadding.length > 0 ? cellPadding : defaultPadding;
};

export const getCellBackgroundColorResolver: Resolver<string | undefined> = content => {
  if (Array.isArray(content) && content.length > 0) {
    return content.find(node => node.type.name === TIPTAP_TABLE_CELL_TYPE)?.attrs?.cellStyle
      ?.backgroundColor;
  }
  return undefined;
};

export const getCellBackgroundColorsResolver: Resolver<string[]> = (_, __, editor) => {
  if (!findTable(editor!.state.selection) || !isRicosCellSelection(editor!.state.selection)) {
    return [];
  }

  const colors = new Set<string>();
  editor!.state.selection.forEachCell(node => {
    const backgroundColor: string | undefined = node.attrs?.cellStyle?.backgroundColor;
    colors.add(
      backgroundColor && backgroundColor !== TRANSPARENT_HEX_COLOR
        ? backgroundColor
        : TRANSPARENT_HEX_COLOR
    );
  });

  return [...colors];
};

const BORDER_SIDES = ['top', 'right', 'bottom', 'left'] as const;

export const getCellBorderColorsResolver: Resolver<string[]> = (_, __, editor) => {
  if (!findTable(editor!.state.selection) || !isRicosCellSelection(editor!.state.selection)) {
    return [];
  }

  const defaultColor = resolveDefaultBorderColor(editor!.view.dom as HTMLElement);
  const table = TableQuery.of(editor!.state.selection);
  if (!table) {
    return [];
  }

  // Borders are display-resolved: a shared edge can be owned by the neighbour cell and
  // defaults come from the grid logic. Resolve the displayed border per side so the swatch
  // reflects what the user actually sees, not just the raw per-cell attrs.
  const tableNode = table.getNode();
  const tableStart = table.getStartPos();
  const cellSpacing = (tableNode.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
  const resolvedBorders = resolveCellBordersPm(tableNode, {
    drawDefaultGrid: true,
    cellSpacing,
  });
  const colors = new Set<string>();

  editor!.state.selection.forEachCell((node, pos) => {
    const cell = table.map.findCell(pos - tableStart);
    for (const side of BORDER_SIDES) {
      const border = getDisplayedBorderOnSide(
        resolvedBorders,
        tableNode,
        node.attrs.id,
        cell,
        side
      );
      colors.add(resolveDisplayedBorderColor(border?.color, defaultColor));
    }
  });

  return [...colors];
};

// -- Node/table-level resolvers --

export const selectedNodeResolver: Resolver<Node | undefined> = (_, __, editor) => {
  if (findTable(editor!.state.selection)) {
    const table = TableQuery.of(editor!.state.selection);
    return table?.getNode();
  }
  return undefined;
};

export const firstSelectedCellIdResolver: Resolver<string | undefined> = (_, __, editor) => {
  if (!findTable(editor!.state.selection) || !isRicosCellSelection(editor!.state.selection)) {
    return undefined;
  }

  let firstCellId: string | undefined;
  editor!.state.selection.forEachCell(node => {
    if (firstCellId === undefined) {
      firstCellId = node.attrs.id;
    }
  });

  return firstCellId;
};

export const selectedCellIdsResolver: Resolver<string[]> = (_, __, editor) => {
  if (!findTable(editor!.state.selection) || !isRicosCellSelection(editor!.state.selection)) {
    return [];
  }

  const selectedCellIds: string[] = [];
  editor!.state.selection.forEachCell(node => {
    if (node.attrs.id) {
      selectedCellIds.push(node.attrs.id);
    }
  });

  return selectedCellIds;
};

export const getVerticalAlignmentResolver: Resolver<string | undefined> = content => {
  if (Array.isArray(content) && content.length > 0) {
    const cellNode = content.find(node => node.type.name === TIPTAP_TABLE_CELL_TYPE);
    return cellNode?.attrs?.cellStyle?.verticalAlignment || 'TOP';
  }
  return undefined;
};

// -- Selection state resolvers --

export const isTableSelectedResolver: Resolver<boolean> = (_, __, editor) => {
  if (findTable(editor!.state.selection)) {
    const table = TableQuery.of(editor!.state.selection);
    return table?.isTableSelected() ?? false;
  }
  return false;
};

export const isCellSelectionResolver: Resolver<boolean> = (_, __, editor) => {
  return getSelectionContext(editor!) !== null;
};

export const isColumnSelectedResolver: Resolver<boolean> = (_, __, editor) => {
  const ctx = getSelectionContext(editor!);
  return ctx ? isFullAxisSelected(ctx, 'col') : false;
};

export const isRowSelectedResolver: Resolver<boolean> = (_, __, editor) => {
  const ctx = getSelectionContext(editor!);
  return ctx ? isFullAxisSelected(ctx, 'row') : false;
};

export const isRowColOrTableSelectedResolver: Resolver<boolean> = (_, __, editor) => {
  const { selection } = editor!.state;
  if (!findTable(selection) || !isRicosCellSelection(selection)) {
    return false;
  }

  const table = TableQuery.of(selection);
  if (!table) {
    return false;
  }

  const isEntireTableSelected = table.isTableSelected();
  const isRowSelected = selection.isRowSelection?.();
  const isColSelected = selection.isColSelection?.();
  const isMultipleRowsSelected = table.getRowsIndexesInSelection().length > 1;
  const isMultipleColsSelected = table.getColsIndexesInSelection().length > 1;

  if (isEntireTableSelected) {
    return true;
  }
  if (isRowSelected && !isMultipleRowsSelected) {
    return true;
  }
  if (isColSelected && !isMultipleColsSelected) {
    return true;
  }
  return false;
};

export const getSelectionCategoryResolver: Resolver<TableSelectionCategory | undefined> = (
  _,
  __,
  editor
) => {
  const { selection } = editor!.state;
  if (!findTable(selection)) {
    return undefined;
  }

  const table = TableQuery.of(selection);
  if (!table || !isRicosCellSelection(selection)) {
    return undefined;
  }

  const isColSelected = selection.isColSelection?.();
  const isRowSelected = selection.isRowSelection?.();
  const isEntireTableSelected = table.isTableSelected();
  const isMultipleRowsSelected = table.getRowsIndexesInSelection().length > 1;
  const isMultipleColsSelected = table.getColsIndexesInSelection().length > 1;

  return (
    (isEntireTableSelected && CATEGORY.ENTIRE_TABLE) ||
    (isColSelected && !isMultipleColsSelected && CATEGORY.COLUMN) ||
    (isRowSelected && !isMultipleRowsSelected && CATEGORY.ROW) ||
    (isMultipleRowsSelected && isMultipleColsSelected && CATEGORY.RANGE) ||
    (isMultipleRowsSelected && CATEGORY.ROW_RANGE) ||
    (isMultipleColsSelected && CATEGORY.COLUMN_RANGE) ||
    CATEGORY.CELL_BORDER
  );
};

// -- Move/merge/split resolvers --

export const cannotMoveColumnLeftResolver: Resolver<boolean> = (_, __, editor) =>
  cannotMove(editor!, 'col', 'start');

export const cannotMoveColumnRightResolver: Resolver<boolean> = (_, __, editor) =>
  cannotMove(editor!, 'col', 'end');

export const cannotMoveRowUpResolver: Resolver<boolean> = (_, __, editor) =>
  cannotMove(editor!, 'row', 'start');

export const cannotMoveRowDownResolver: Resolver<boolean> = (_, __, editor) =>
  cannotMove(editor!, 'row', 'end');

export const cannotMergeCellsResolver: Resolver<boolean> = (_, __, editor) => {
  const { state } = editor!;
  if (!findTable(state.selection)) {
    return true;
  }
  const canMerge = mergeCells(state, () => null);
  return !canMerge;
};

export const cannotSplitCellResolver: Resolver<boolean> = (_, __, editor) => {
  const { state } = editor!;
  if (!findTable(state.selection)) {
    return true;
  }
  const canSplit = splitCell(state, () => null);
  return !canSplit;
};

// -- Helper functions used by button definitions --

export const isFirstColumnSelected = (editor: Editor): boolean => {
  if (findTable(editor.state.selection)) {
    const table = TableQuery.of(editor.state.selection);
    return table?.isColumnSelected(0) ?? false;
  }
  return false;
};

export const isFirstRowSelected = (editor: Editor): boolean => {
  if (findTable(editor.state.selection)) {
    const table = TableQuery.of(editor.state.selection);
    return table?.isRowSelected(0) ?? false;
  }
  return false;
};
