import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import { More } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useState } from 'react';

import type { IToolbarItem, RicosServices } from './../../../ricos-types/index.js';
import { createPluginToolbarButton } from './../../../_shared/create-plugin-toolbar-button.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';

import { CATEGORY, TABLE_BUTTONS, TABLE_BUTTONS_MODALS_ID } from '../../consts.js';
import { PLUGIN_TOOLBAR_CONTEXT_MENU_BUTTON } from '../../data-hooks.js';
import { toggleHeader } from '../../tiptap/commands/mutations.js';
import { TABLE_TYPE } from '../../types.js';
import { CONTEXT_PANEL_OPTIONS } from '../modals/consts.js';
import { ContextDropdown } from '../modals/context-dropdown.js';
import {
  getSelectionCategoryResolver,
  isFirstColumnSelected,
  isFirstRowSelected,
  selectedNodeResolver,
} from '../resolvers.js';

const NoIcon: React.FC = () => null;

interface Props {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}

export const ContextButton: FC<Props> = ({ dataHook, toolbarItem }) => {
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);

  return (
    <ToolbarButtonComponent
      dataHook={dataHook}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      ref={setReferenceElement}
      prefix={More}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};

export const createContextButton = (services: RicosServices) =>
  createPluginToolbarButton({
    id: TABLE_BUTTONS.CONTEXT,
    type: 'modal',
    dataHook: PLUGIN_TOOLBAR_CONTEXT_MENU_BUTTON,
    tooltip: null,
    icon: More,
    getComponentProps: ({ tiptapEditor, attributes, t }) => {
      const category = attributes?.selectedCategory;
      const contextOptions = CONTEXT_PANEL_OPTIONS[category] || [];
      const showRowHeaderToggle =
        (category === CATEGORY.ENTIRE_TABLE || isFirstRowSelected(tiptapEditor)) &&
        toggleHeader('row')(tiptapEditor.state);
      const showColumnHeaderToggle =
        (category === CATEGORY.ENTIRE_TABLE || isFirstColumnSelected(tiptapEditor)) &&
        toggleHeader('column')(tiptapEditor.state);

      const options: { id: string; icon: IconComponent; label: string }[] = [];

      if (showRowHeaderToggle) {
        options.push({
          id: 'toggleHeaderRow',
          icon: NoIcon,
          label: t('TablePlugin_Toolbar_ContextMenu_HeaderRow_Title'),
        });
      }
      if (showColumnHeaderToggle) {
        options.push({
          id: 'toggleHeaderColumn',
          icon: NoIcon,
          label: t('TablePlugin_Toolbar_ContextMenu_HeaderColumn_Title'),
        });
      }

      contextOptions.forEach(option => {
        if (option !== 'divider') {
          options.push({
            id: option.commandKey,
            icon: option.iconSmall,
            label: t(option.title),
          });
        }
      });

      return {
        options,
        onSelect: (commandKey: string) => {
          // @ts-expect-error dynamic command access
          tiptapEditor.chain().focus()[commandKey]().run();
        },
      };
    },
    command: ({ tiptapEditor, modals, attributes, referenceElement }) => {
      const closeModal = () => modals.closeModal(TABLE_BUTTONS_MODALS_ID.CONTEXT);
      const isModalOpen = modals.isModalOpen(TABLE_BUTTONS_MODALS_ID.CONTEXT);

      if (isModalOpen) {
        closeModal();
        return;
      }

      const category = attributes?.selectedCategory;
      const nodeId = attributes?.selectedNode?.attrs?.id;
      const tableAttrs = attributes?.selectedNode?.attrs || {};
      const showRowHeaderToggle =
        (category === CATEGORY.ENTIRE_TABLE || isFirstRowSelected(tiptapEditor)) &&
        toggleHeader('row')(tiptapEditor.state);
      const showColumnHeaderToggle =
        (category === CATEGORY.ENTIRE_TABLE || isFirstColumnSelected(tiptapEditor)) &&
        toggleHeader('column')(tiptapEditor.state);

      modals.openModal({
        id: TABLE_BUTTONS_MODALS_ID.CONTEXT,
        Component: ContextDropdown,
        componentProps: {
          onClick: data => {
            const chain = tiptapEditor.chain().focus();
            if (data.commandKey === 'toggleHeaderRow') {
              chain.toggleHeaderRow().run();
              return;
            } else if (data.commandKey === 'toggleHeaderColumn') {
              chain.toggleHeaderColumn().run();
              return;
            } else {
              // @ts-expect-error dynamic command access
              chain[data.commandKey]().run();
            }
            closeModal();
          },
          closeModal,
          category,
          nodeId,
          showRowHeaderToggle,
          showColumnHeaderToggle,
          rowHeaderActive: !!tableAttrs.tableData?.rowHeader,
          columnHeaderActive: !!tableAttrs.tableData?.columnHeader,
          ...(category === CATEGORY.ENTIRE_TABLE
            ? {
                altText: tableAttrs.tableData?.altText || '',
                onAltTextChange: (text: string) => {
                  tiptapEditor.chain().setTableAltText(text).run();
                },
              }
            : {}),
        },
        layout: services.context.isMobile ? 'drawer' : 'floating',
        positioning: { referenceElement, placement: 'bottom' },
      });

      services.pluginsEvents.publishTableContextMenuClick({
        pluginId: TABLE_TYPE,
        nodeId,
        category,
      });
    },
    attributes: {
      selectedCategory: getSelectionCategoryResolver,
      selectedNode: selectedNodeResolver,
    },
    renderer: toolbarItem => <ContextButton toolbarItem={toolbarItem} />,
  });
