import type { Editor } from './../../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';

import { DATA_CELL_SELECTED } from '../data-hooks.js';
import { RicosCellSelection } from '../tiptap/plugins/cellselection.js';
import { findTable } from '../tiptap/utilities/find-table.js';
import { isRicosCellSelection } from '../tiptap/utilities/is-selection-type.js';

export type CapturedCell = { element?: HTMLElement; id?: string; pos: number };
export type CapturedTableCellSelection = CapturedCell[] | null;

const findCellDomById = (editor: Editor, id: string): HTMLElement | undefined => {
  const dom = [...editor.view.dom.querySelectorAll('[data-node-id]')].find(
    element => element.getAttribute('data-node-id') === id
  );
  return dom instanceof HTMLElement ? dom : undefined;
};

const getCellElement = (editor: Editor, pos: number, id?: string): HTMLElement | undefined => {
  const dom = editor.view.nodeDOM(pos);
  if (dom instanceof HTMLElement) {
    return dom;
  }
  return id ? findCellDomById(editor, id) : undefined;
};

/** Walk only the table containing `selection` (or `firstId`) instead of the entire doc. */
const captureCellsById = (
  editor: Editor,
  selectedCellIds: readonly string[] | undefined
): CapturedTableCellSelection => {
  if (!selectedCellIds?.length) {
    return null;
  }

  const selectedIds = new Set(selectedCellIds);
  const tableInfo = findTable(editor.state.selection);
  const cells: CapturedCell[] = [];

  const visit = (node: ProseMirrorNode, basePos: number) => {
    node.descendants((child, offset) => {
      const id = child.attrs.id as string | undefined;
      if (id && selectedIds.has(id)) {
        cells.push({
          element: getCellElement(editor, basePos + offset, id),
          id,
          pos: basePos + offset,
        });
      }
    });
  };

  if (tableInfo) {
    visit(tableInfo.node, tableInfo.start);
  } else {
    // Fallback: selection is no longer inside the table — search the whole doc once.
    visit(editor.state.doc, 0);
  }

  return cells.length > 0 ? cells : null;
};

const captureCellsFromDom = (editor: Editor): CapturedTableCellSelection => {
  const { view } = editor;
  const cells: CapturedCell[] = [];
  for (const element of view.dom.querySelectorAll(`[${DATA_CELL_SELECTED}="true"]`)) {
    if (!(element instanceof HTMLElement) || !view.dom.contains(element)) {
      continue;
    }
    try {
      cells.push({
        element,
        id: element.getAttribute('data-node-id') ?? undefined,
        pos: view.posAtDOM(element, 0),
      });
    } catch {
      // posAtDOM throws when the element is not inside an editable node — skip it.
    }
  }
  return cells.length > 0 ? cells : null;
};

export const captureSelectedCellPositions = (
  editor: Editor,
  selectedCellIds?: readonly string[]
): CapturedTableCellSelection => {
  const { selection } = editor.state;
  if (isRicosCellSelection(selection)) {
    const cells: CapturedCell[] = [];
    selection.forEachCell((node, pos) => {
      cells.push({ element: getCellElement(editor, pos, node.attrs.id), id: node.attrs.id, pos });
    });
    if (cells.length > 0) {
      return cells;
    }
  }

  return captureCellsFromDom(editor) ?? captureCellsById(editor, selectedCellIds);
};

/**
 * Restores a {@link RicosCellSelection} from captured positions (if needed) and runs `run`.
 * Skips the selection-restore dispatch when the live editor selection is already a cell selection.
 * The selection-restore tr is marked as not-undoable so the user's undo stack sees a single entry.
 */
export const runWithTableCellSelection = (
  editor: Editor,
  capturedCells: CapturedTableCellSelection,
  run: () => void
): void => {
  if (!isRicosCellSelection(editor.state.selection) && capturedCells?.length) {
    const { state, view } = editor;
    try {
      const cells = capturedCells.map(({ pos }) => state.doc.resolve(pos));
      view.dispatch(
        state.tr
          .setSelection(new RicosCellSelection(cells, state.doc))
          .setMeta('addToHistory', false)
      );
    } catch {
      // Captured positions no longer resolve — fall through and let `run` use the live selection.
    }
  }
  run();
};
