import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { EditorState, Transaction } from './../../tiptap/pm/state.js';

import { applyBorderEdit, extractCellPositions } from '../borders/canonical-remap.js';
import {
  type CellPosition,
  type Side,
  buildCellGrid,
  getCellAt,
  groupOuterEdgeCells,
  isCellOuterEdge,
} from '../borders/edge-detection.js';
import { TableQuery } from '../tiptap/table-query.js';
import { isRicosCellSelection } from '../tiptap/utilities/is-selection-type.js';
import type { BordersType } from '../types.js';

type SelectedCell = { node: ProseMirrorNode; pos: number };
type BorderStyle = { color?: string; width?: number };

type SelectionContext = {
  tableStart: number;
  width: number;
  height: number;
  allSelectedCells: SelectedCell[];
  cellsById: Map<string, CellPosition>;
  isCellInSelection: (row: number, col: number) => boolean;
};

const getSelectionContext = (state: EditorState): SelectionContext | null => {
  const { selection } = state;
  const table = TableQuery.of(selection);
  if (!table || !isRicosCellSelection(selection)) {
    return null;
  }

  const tableNode = table.getNode();
  const tableStart = table.getStartPos();
  const { cells, width, height } = extractCellPositions(tableNode, tableStart);
  const allSelectedCells: SelectedCell[] = [];
  const selectedCellIds = new Set<string>();

  selection.forEachCell((node, pos) => {
    allSelectedCells.push({ node, pos });
    if (node.attrs.id) {
      selectedCellIds.add(node.attrs.id);
    }
  });

  const cellsById = new Map(cells.map(cell => [cell.node.attrs.id, cell]));
  const grid = buildCellGrid(cells, width, height);

  return {
    tableStart,
    width,
    height,
    allSelectedCells,
    cellsById,
    isCellInSelection: (row, col) => {
      const cell = getCellAt(grid, row, col);
      return cell ? selectedCellIds.has(cell.node.attrs.id) : false;
    },
  };
};

/** Re-resolves selected cells against the current tr.doc so positions remain valid mid-transaction. */
const applyEditToCurrentTable = (
  tr: Transaction,
  tableStart: number,
  selected: SelectedCell[],
  side: Side | null,
  style: BorderStyle,
  clear: boolean
): void => {
  const $pos = tr.doc.resolve(tableStart);
  const currentTable = $pos.node($pos.depth);
  if (currentTable?.type.spec.tableRole !== 'table') {
    return;
  }
  const liveCells = selected.flatMap(({ pos }) => {
    const node = tr.doc.nodeAt(pos);
    return node ? [{ node, pos }] : [];
  });
  if (liveCells.length === 0) {
    return;
  }
  applyBorderEdit(tr, currentTable, tableStart, liveCells, side, style, clear);
};

const applyOutsideBorder = (
  tr: Transaction,
  ctx: SelectionContext,
  style: BorderStyle,
  clear: boolean
) => {
  const grouped = groupOuterEdgeCells(
    ctx.allSelectedCells,
    ({ node }) => ctx.cellsById.get(node.attrs.id),
    ctx.width,
    ctx.height,
    ctx.isCellInSelection
  );
  for (const [side, cells] of grouped) {
    if (cells.length > 0) {
      applyEditToCurrentTable(tr, ctx.tableStart, cells, side, style, clear);
    }
  }
};

const applyBorderBySide = (
  tr: Transaction,
  ctx: SelectionContext,
  side: Side,
  style: BorderStyle,
  clear: boolean
) => {
  const outerCells = ctx.allSelectedCells.filter(({ node }) => {
    const cellData = ctx.cellsById.get(node.attrs.id);
    return cellData
      ? isCellOuterEdge(cellData, side, ctx.width, ctx.height, ctx.isCellInSelection)
      : false;
  });
  if (outerCells.length > 0) {
    applyEditToCurrentTable(tr, ctx.tableStart, outerCells, side, style, clear);
  }
};

const applyInnerSide = (
  tr: Transaction,
  ctx: SelectionContext,
  side: 'top' | 'left',
  style: BorderStyle,
  clear: boolean
) => {
  const innerCells = ctx.allSelectedCells.filter(({ node }) => {
    const cellData = ctx.cellsById.get(node.attrs.id);
    if (!cellData) {
      return false;
    }
    return side === 'top'
      ? cellData.row > 0 && ctx.isCellInSelection(cellData.row - 1, cellData.col)
      : cellData.col > 0 && ctx.isCellInSelection(cellData.row, cellData.col - 1);
  });
  if (innerCells.length > 0) {
    applyEditToCurrentTable(tr, ctx.tableStart, innerCells, side, style, clear);
  }
};

export const applyTableBorderChangeToTransaction = (
  tr: Transaction,
  state: EditorState,
  scope: BordersType,
  change: BorderStyle
): boolean => {
  const ctx = getSelectionContext(state);
  if (!ctx) {
    return false;
  }

  const style: BorderStyle =
    change.width !== undefined ? { width: change.width } : { color: change.color };
  // A `color: undefined` change means "clear the color". Width is always set.
  const clear = change.width === undefined && change.color === undefined;

  switch (scope) {
    case 'borders':
      applyEditToCurrentTable(tr, ctx.tableStart, ctx.allSelectedCells, null, style, clear);
      return true;
    case 'outsideBorders':
      applyOutsideBorder(tr, ctx, style, clear);
      return true;
    case 'top':
    case 'right':
    case 'bottom':
    case 'left':
      applyBorderBySide(tr, ctx, scope, style, clear);
      return true;
    case 'inner':
      applyInnerSide(tr, ctx, 'top', style, clear);
      applyInnerSide(tr, ctx, 'left', style, clear);
      return true;
    case 'innerHorizontal':
      applyInnerSide(tr, ctx, 'top', style, clear);
      return true;
    case 'innerVertical':
      applyInnerSide(tr, ctx, 'left', style, clear);
      return true;
    default:
      return false;
  }
};
