import { AllBorders } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type { ModalService } from './../../../ricos-modals/index.js';
import type { IToolbarItem, RicosServices, ToolbarButton } from './../../../ricos-types/index.js';
import { ColorSwatch } from './../../../_shared/plugin-toolbar/color-swatch.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';

import { TABLE_BUTTONS, TABLE_COLOR_PICKER } from '../../consts.js';
import { PLUGIN_TOOLBAR_BORDER_COLOR_BUTTON } from '../../data-hooks.js';
import type { BorderModalProps } from '../../modals/border-modal.js';
import { BorderModal } from '../../modals/border-modal.js';
import { TableQuery } from '../../tiptap/table-query.js';
import { isRicosCellSelection } from '../../tiptap/utilities/is-selection-type.js';
import type { BordersType } from '../../types.js';
import { applyTableBorderChangeToTransaction } from '../apply-table-border-change.js';
import {
  captureSelectedCellPositions,
  runWithTableCellSelection,
} from '../capture-table-cell-selection.js';
import {
  firstSelectedCellIdResolver,
  getCellBorderColorResolver,
  getCellBorderColorsResolver,
  getCellBorderWidthResolver,
  getSelectionCategoryResolver,
  selectedCellIdsResolver,
  selectedNodeResolver,
} from '../resolvers.js';
import { createTableStylePreview } from '../table-style-preview.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const BorderButton: FC<Props> = ({ dataHook, toolbarItem }) => {
  const { t } = useContext(RicosContext);
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);

  const colors: string[] = toolbarItem.attributes.borderColors ?? [];
  const hasColors = colors.length > 0;

  return (
    <ToolbarButtonComponent
      ref={setReferenceElement}
      prefix={hasColors ? () => <ColorSwatch colors={colors} /> : AllBorders}
      onClick={() => {
        toolbarItem.commands.click({ referenceElement });
      }}
      dataHook={dataHook}
      tooltip={t('TablePlugin_Toolbar_Border_Color')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};

const openBorderModal = ({
  modals,
  services,
  referenceElement,
  componentProps,
}: {
  modals: ModalService;
  services: RicosServices;
  referenceElement: HTMLElement | undefined;
  componentProps: BorderModalProps;
}) => {
  modals.togglePluginPanel({
    id: TABLE_COLOR_PICKER,
    isMobile: services.context.isMobile,
    Component: BorderModal,
    positioning: { placement: 'bottom', referenceElement },
    onClickOutside: {
      on: 'pointerup',
      handler: (e: MouseEvent | TouchEvent) => {
        e.preventDefault();
        e.stopPropagation();
      },
    },
    componentProps,
  });
};

export const createBorderButton = (services: RicosServices): ToolbarButton => ({
  id: TABLE_BUTTONS.BORDER,
  type: 'modal',
  dataHook: PLUGIN_TOOLBAR_BORDER_COLOR_BUTTON,
  icon: AllBorders,
  tooltip: 'TablePlugin_Toolbar_Border_Color',
  command: ({ tiptapEditor, attributes, modals, referenceElement }) => {
    const table = TableQuery.of(tiptapEditor.state.selection);
    const rowsCount = table?.getRowsIndexesInSelection().length ?? 0;
    const colsCount = table?.getColsIndexesInSelection().length ?? 0;
    const canInnerHorizontal = rowsCount > 1;
    const canInnerVertical = colsCount > 1;

    let currentBorderScope: BordersType = 'borders';

    const handleBorderScopeChange = (scope: BordersType) => {
      currentBorderScope = scope;
    };

    const selectedCellPositions = captureSelectedCellPositions(
      tiptapEditor,
      attributes?.selectedCellIds
    );
    const borderPreview = createTableStylePreview(tiptapEditor, selectedCellPositions);

    const handleOnChange = (color?: string, width?: number) => {
      // Re-establish the cell selection on the live state first, then build the mutation
      // transaction against that live state so view.dispatch receives a tr rooted in the
      // editor's current state (not a synthesised one).
      runWithTableCellSelection(tiptapEditor, selectedCellPositions, () => {
        const { state, view } = tiptapEditor;
        if (!isRicosCellSelection(state.selection)) {
          return;
        }
        const tr = state.tr;
        const change = width !== undefined ? { width } : { color };
        if (
          applyTableBorderChangeToTransaction(tr, state, currentBorderScope, change) &&
          tr.docChanged
        ) {
          view.dispatch(tr);
        }
      });
    };

    openBorderModal({
      services,
      referenceElement,
      modals,
      componentProps: {
        referenceElement,
        nodeId: attributes?.firstSelectedCellId,
        color: attributes?.cellBorderColor,
        borderWidth: attributes?.cellBorderWidth,
        borderScope: 'borders',
        onBorderScopeChange: handleBorderScopeChange,
        canInnerHorizontal,
        canInnerVertical,
        onColorPreview: color => {
          borderPreview.previewBorder(currentBorderScope, { color });
        },
        onColorPreviewEnd: () => {
          borderPreview.restore();
        },
        onColorCommit: color => {
          borderPreview.restore();
          queueMicrotask(() => handleOnChange(color, undefined));
        },
        onBorderWidthPreview: width => {
          borderPreview.previewBorder(currentBorderScope, { width });
        },
        onBorderWidthCommit: finalValue => {
          borderPreview.restore();
          queueMicrotask(() => handleOnChange(undefined, finalValue));
        },
      },
    });
  },
  attributes: {
    cellBorderColor: getCellBorderColorResolver,
    cellBorderWidth: getCellBorderWidthResolver,
    borderColors: getCellBorderColorsResolver,
    selectedCategory: getSelectionCategoryResolver,
    selectedNode: selectedNodeResolver,
    firstSelectedCellId: firstSelectedCellIdResolver,
    selectedCellIds: selectedCellIdsResolver,
  },
  renderer: toolbarItem => <BorderButton toolbarItem={toolbarItem} />,
});
