import React from 'react';

import type { RicosServices } from './../../../ricos-types/index.js';
import { createPluginToolbarButton } from './../../../_shared/create-plugin-toolbar-button.js';
import { VERTICAL_ALIGNMENT_BUTTONS } from './../../../toolbars-v3/components/buttons/VerticalAlignmentButton/vertical-alignment-dropdown.js';
import {
  VERTICAL_ALIGNMENT_MODAL_ID,
  VerticalAlignmentButton,
  VerticalAlignmentDropdown,
  verticalAlignmentIcons,
} from './../../../toolbars-v3/index.js';

import { TABLE_BUTTONS } from '../../consts.js';
import { PLUGIN_TOOLBAR_VERTICAL_ALIGNMENT_BUTTON } from '../../data-hooks.js';
import { getVerticalAlignmentResolver } from '../resolvers.js';

export const createVerticalAlignmentButton = (services: RicosServices) =>
  createPluginToolbarButton({
    id: TABLE_BUTTONS.VERTICAL_ALIGNMENT,
    type: 'dropdown',
    dataHook: PLUGIN_TOOLBAR_VERTICAL_ALIGNMENT_BUTTON,
    getIcon: ({ attributes }) => {
      const verticalAlignment: 'TOP' | 'MIDDLE' | 'BOTTOM' = attributes.verticalAlignment;
      return verticalAlignmentIcons[verticalAlignment];
    },
    tooltip: 'Toolbar_VerticalAlignment_Tooltip',
    Component: VerticalAlignmentDropdown,
    getComponentProps: ({ tiptapEditor, modals, attributes }) => {
      return {
        onSelect: (verticalAlignment: 'TOP' | 'MIDDLE' | 'BOTTOM') => {
          tiptapEditor
            .chain()
            .focus()
            .updateCellAttribute('cellStyle', { verticalAlignment })
            .run();
        },
        selectedId: attributes.verticalAlignment,
        dropdownOptions: Object.values(VERTICAL_ALIGNMENT_BUTTONS).map(item => ({
          id: item.commandKey,
          dataHook: item.dataHook,
          label: services.t(item.tooltip),
          icon: item.iconSmall,
          iconMobile: item.icon,
        })),
        closeModal: () => modals.closeModal(VERTICAL_ALIGNMENT_MODAL_ID),
      };
    },
    command: ({
      modals,
      referenceElement,
      getComponentProps,
      tiptapEditor,
      attributes,
      publicCommands,
    }) => {
      const closeModal = () => modals.closeModal(VERTICAL_ALIGNMENT_MODAL_ID);
      const isModalOpen = modals.isModalOpen(VERTICAL_ALIGNMENT_MODAL_ID);

      if (isModalOpen) {
        closeModal();
        return;
      }

      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      modals.openModal({
        id: VERTICAL_ALIGNMENT_MODAL_ID,
        Component: VerticalAlignmentDropdown,
        componentProps,
        layout: services.context.isMobile ? 'drawer' : 'floating',
        positioning: { referenceElement, placement: 'bottom' },
      });
    },
    attributes: {
      verticalAlignment: getVerticalAlignmentResolver,
    },
    renderer: toolbarItem => <VerticalAlignmentButton toolbarItem={toolbarItem} />,
  });
