import { Box, ToggleButton } from '@wix/design-system';
import { CellBorders, CellBordersSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import type { BordersType } from '../../types.js';
import styles from './border-scope-selector-scss.js';

export const BORDER_SCOPE_BUTTON_PREFIX = 'border-scope-';

export interface BorderScopeSelectorProps {
  selectedScope: BordersType;
  onScopeChange: (scope: BordersType) => void;
  canInnerHorizontal: boolean;
  canInnerVertical: boolean;
}

type BorderState = {
  top: boolean;
  right: boolean;
  bottom: boolean;
  left: boolean;
  middleH: boolean;
  middleV: boolean;
};

interface ScopeOption {
  type: BordersType;
  borders: BorderState;
  labelKey: string;
  getDisabled?: (props: { canInnerH: boolean; canInnerV: boolean }) => boolean;
}

const SCOPE_OPTIONS: ScopeOption[] = [
  {
    type: 'borders',
    borders: {
      top: true,
      right: true,
      bottom: true,
      left: true,
      middleH: true,
      middleV: true,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_AllBorders',
  },
  {
    type: 'outsideBorders',
    borders: {
      top: true,
      right: true,
      bottom: true,
      left: true,
      middleH: false,
      middleV: false,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_OuterBorders',
  },
  {
    type: 'top',
    borders: {
      top: true,
      right: false,
      bottom: false,
      left: false,
      middleH: false,
      middleV: false,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_TopBorder',
  },
  {
    type: 'left',
    borders: {
      top: false,
      right: false,
      bottom: false,
      left: true,
      middleH: false,
      middleV: false,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_LeftBorder',
  },
  {
    type: 'right',
    borders: {
      top: false,
      right: true,
      bottom: false,
      left: false,
      middleH: false,
      middleV: false,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_RightBorder',
  },
  {
    type: 'bottom',
    borders: {
      top: false,
      right: false,
      bottom: true,
      left: false,
      middleH: false,
      middleV: false,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_BottomBorder',
  },
  {
    type: 'inner',
    borders: {
      top: false,
      right: false,
      bottom: false,
      left: false,
      middleH: true,
      middleV: true,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_AllInner',
    getDisabled: ({ canInnerH, canInnerV }) => !canInnerH || !canInnerV,
  },
  {
    type: 'innerHorizontal',
    borders: {
      top: false,
      right: false,
      bottom: false,
      left: false,
      middleH: true,
      middleV: false,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_InnerHorizontal',
    getDisabled: ({ canInnerH }) => !canInnerH,
  },
  {
    type: 'innerVertical',
    borders: {
      top: false,
      right: false,
      bottom: false,
      left: false,
      middleH: false,
      middleV: true,
    },
    labelKey: 'TablePlugin_Toolbar_BorderScope_InnerVertical',
    getDisabled: ({ canInnerV }) => !canInnerV,
  },
];

const getBorderFills = (borders: BorderState, isDisabled?: boolean) => {
  const activeColor = isDisabled ? '#969696' : 'currentColor';
  return {
    '--border-top-fill': borders.top ? activeColor : 'transparent',
    '--border-right-fill': borders.right ? activeColor : 'transparent',
    '--border-bottom-fill': borders.bottom ? activeColor : 'transparent',
    '--border-left-fill': borders.left ? activeColor : 'transparent',
    '--border-middle-h-fill': borders.middleH ? activeColor : 'transparent',
    '--border-middle-v-fill': borders.middleV ? activeColor : 'transparent',
  } as React.CSSProperties;
};

export const BorderScopeSelector: React.FC<BorderScopeSelectorProps> = ({
  selectedScope,
  onScopeChange,
  canInnerHorizontal,
  canInnerVertical,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  const Icon = isMobile ? CellBorders : CellBordersSmall;

  // Split options into rows of 3
  const rows = [SCOPE_OPTIONS.slice(0, 3), SCOPE_OPTIONS.slice(3, 6), SCOPE_OPTIONS.slice(6, 9)];

  return (
    <Box padding="18px" direction="vertical" gap="6px" align="center">
      {rows.map((row, rowIndex) => (
        <Box key={rowIndex} gap="6px">
          {row.map(option => {
            const isDisabled = option.getDisabled?.({
              canInnerH: canInnerHorizontal,
              canInnerV: canInnerVertical,
            });
            const isSelected = selectedScope === option.type;

            return (
              <ToggleButton
                key={option.type}
                dataHook={`${BORDER_SCOPE_BUTTON_PREFIX}${option.type}`}
                size={isMobile ? 'small' : 'medium'}
                shape="square"
                selected={isSelected}
                disabled={isDisabled}
                labelValue={t(option.labelKey)}
                labelPlacement="tooltip"
                onClick={() => !isDisabled && onScopeChange(option.type)}
              >
                <Box position="relative">
                  <Icon size={isMobile ? 18 : 24} className={styles.cellBordersIconBase} />
                  <Icon
                    size={isMobile ? 18 : 24}
                    className={styles.cellBordersIconOverlay}
                    style={getBorderFills(option.borders, isDisabled)}
                  />
                </Box>
              </ToggleButton>
            );
          })}
        </Box>
      ))}
    </Box>
  );
};
